const http = require("http");

const server = http.createServer((req, res) => {
  if (req.url === "/api/design-review" && req.method === "POST") {
    let body = "";
    req.on("data", chunk => {
      body += chunk.toString();
    });
    req.on("end", () => {
      console.log("Received design review registration:", body);
      res.writeHead(201, {"Content-Type": "application/json"});
      res.end(JSON.stringify({status: "registered", reviewId: "rvw_123"}));
    });
  } else {
    res.writeHead(404);
    res.end();
  }
});

server.listen(3003, () => {
  console.log("Design tracking service listening on http://localhost:3003");
});
